using OcctSharp.DocumentProjections;
using OcctSharp.Tests.Shared;
namespace OcctSharp.Runtime.Tests;
public sealed class DirectCollectionTests {
 static readonly string[] InvalidUtf16=["\uD800"];
 static readonly int[] ExpectedOriginal=[4,5];
 [Fact]public void EmptyArrayBackupsRestoreExactBoundsThroughAbortUndoRedo(){using var document=DocumentProjectionContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(document);var label=context.GetLabel("0:1");DirectCollectionUpdate[] updates=[new(label,DirectCollectionKind.IntegerArray,DirectCollections.Array<int>(9,[])),new(label,DirectCollectionKind.RealArray,DirectCollections.Array<double>(-3,[])),new(label,DirectCollectionKind.StringArray,DirectCollections.Array<string>(17,[])),new(label,DirectCollectionKind.ByteArray,DirectCollections.Array<byte>(-6,[])),new(label,DirectCollectionKind.ReferenceArray,DirectCollections.Array<DocumentProjectionLabel?>(4,[]))];void Verify(){foreach(var row in updates){var copy=context.ReadCollection(label,row.Kind);Assert.NotNull(copy);Assert.Equal(0,copy.Value.Count);Assert.Equal(row.Value!.LowerBound,copy.Value.LowerBound);}}document.NewCommand();context.ReplaceCollections(updates);Assert.True(document.CommitCommand());Verify();document.NewCommand();foreach(var row in updates)context.RemoveCollection(label,row.Kind);document.AbortCommand();Verify();document.NewCommand();foreach(var row in updates)context.RemoveCollection(label,row.Kind);Assert.True(document.CommitCommand());foreach(var row in updates)Assert.Null(context.ReadCollection(label,row.Kind));Assert.True(document.Undo());Verify();Assert.True(document.Redo());foreach(var row in updates)Assert.Null(context.ReadCollection(label,row.Kind));Assert.True(document.Undo());Verify();}
 [Fact]public void NineTypedFamiliesActualPersistenceAndRepeatedOccurrenceIsolation()=>BatchBICollectionWorkflow.Run();
 [Fact]public void DeliveredCoupledIntersectionSourceMutationStaysIsolatedBeforeDocumentProjection(){using var first=OcctSharp.CopiedCollections.GeomBSplineSurfaceCollections.Create(new([new OcctSharp.Values.Coordinates3d(0,0,0),new(0,2,0),new(2,0,0),new(2,2,0)],2,2),new([0.0,1]),new([0.0,1]),new([2,2]),new([2,2]),1,1,false,false);using var secondFace=BatchBHIntersectionWorkflow.Vertical();using var second=OcctSharp.IntersectionResults.RayIntersections.CopySurface(secondFace);using var result=OcctSharp.IntersectionResults.SurfaceIntersections.Compute(first,second);Assert.True(result.IsDone);Assert.NotEmpty(result.Lines);using var source=result.CopySourceSurface(0);var before=BatchBHIntersectionWorkflow.Eval(source,0,0);OcctSharp.CopiedCollections.GeomBSplineSurfaceCollections.SetPoleRow(first,1,new([new OcctSharp.Values.Coordinates3d(100,100,100),new(100,102,100)]));var after=BatchBHIntersectionWorkflow.Eval(source,0,0);Assert.Equal(before,after);using var line=result.CopyLine(1);var info=result.Lines[0];double t=info.Parameters.First??0;var point=line.Curve.Value(t);using var document=DocumentProjectionContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(document);var label=context.GetLabel("0:1");document.NewCommand();context.ReplaceCollection(label,DirectCollections.Array<double>(-3,[point.X,point.Y,point.Z]));context.ReplaceCollection(label,DirectCollections.List<string>([result.Identity.ToString("D")]));Assert.True(document.CommitCommand());Assert.Equal(new[]{point.X,point.Y,point.Z},BatchBICollectionWorkflow.Read<double>(context,label,DirectCollectionKind.RealArray).Values);}
 [Fact]public void InputCopiesUnicodeFinitenessAndBoundsArePreserved(){int[] source=[1,2];var copy=DirectCollections.Array(-4,source);source[0]=99;Assert.Equal(1,copy.Values[0]);Assert.Throws<NotSupportedException>(()=>((IList<int>)copy.Values)[0]=1);Assert.Throws<ArgumentException>(()=>DirectCollections.Array<double>(0,[double.NaN]));Assert.Throws<ArgumentException>(()=>DirectCollections.List<string>(["a\0b"]));Assert.Throws<System.Text.EncoderFallbackException>(()=>DirectCollections.List(InvalidUtf16));Assert.Throws<ArgumentOutOfRangeException>(()=>DirectCollections.Array<int>(int.MinValue,[1]));Assert.Throws<NotSupportedException>(()=>DirectCollections.Array(1,Array.Empty<bool>()));Assert.Throws<NotSupportedException>(()=>DirectCollections.List<byte>([1]));}
 [Fact]public void LazyValueAndUpdateInputsStopAtBudgetPlusOne(){int values=0;IEnumerable<int> Endless(){while(true){++values;yield return 1;}}Assert.Throws<ArgumentOutOfRangeException>(()=>DirectCollections.Array(0,Endless()));Assert.Equal(1048577,values);using var document=DocumentProjectionContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(document);var label=context.GetLabel("0:1");int rows=0;IEnumerable<DirectCollectionUpdate> Updates(){while(true){++rows;yield return new(label,DirectCollectionKind.IntegerArray,null);}}Assert.Throws<ArgumentOutOfRangeException>(()=>context.ReplaceCollections(Updates()));Assert.Equal(4097,rows);Assert.Null(context.ReadCollection(label,DirectCollectionKind.IntegerArray));}
 [Fact]public void ExistingCommandGuidTypeAndDuplicateTargetsAreValidatedBeforePublication(){using var document=DocumentProjectionContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(document);var label=context.GetLabel("0:1");Assert.ThrowsAny<Exception>(()=>context.ReplaceCollection(label,DirectCollections.Array<int>(0,[1])));document.NewCommand();context.ReplaceCollection(label,DirectCollections.Array<int>(0,[1]));var before=context.Snapshot(label).SubtreeAttributeCount;Assert.ThrowsAny<Exception>(()=>context.ReplaceCollections([new(label,DirectCollectionKind.IntegerArray,DirectCollections.Array<int>(0,[2])),new(label,DirectCollectionKind.IntegerArray,null)]));Assert.Equal(1,BatchBICollectionWorkflow.Read<int>(context,label,DirectCollectionKind.IntegerArray).Values.Single());var id=context.ReadCollection(label,DirectCollectionKind.IntegerArray)!.AttributeId;Assert.ThrowsAny<Exception>(()=>context.ReplaceCollection(label,DirectCollections.List<string>(["wrong type"]),id));Assert.Equal(before,context.Snapshot(label).SubtreeAttributeCount);Assert.True(document.CommitCommand());}
 [Fact]public void ReferenceDomainAndClosedDocumentCannotBeRebound(){using var document=DocumentProjectionContext.CreateNativeDocument();using var other=DocumentProjectionContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(document);using var foreign=DocumentProjectionContext.Bind(other);using var anotherView=DocumentProjectionContext.Bind(document);var label=context.GetLabel("0:1");document.NewCommand();Assert.Throws<ArgumentException>(()=>context.ReplaceCollection(label,DirectCollections.Array<DocumentProjectionLabel?>(0,[foreign.GetLabel("0:1")])));Assert.Throws<ArgumentException>(()=>context.ReplaceCollection(label,DirectCollections.Array<DocumentProjectionLabel?>(0,[anotherView.GetLabel("0:1")])));context.ReplaceCollection(label,DirectCollections.Array<DocumentProjectionLabel?>(0,[label,null]));Assert.True(document.CommitCommand());var references=BatchBICollectionWorkflow.Read<DocumentProjectionLabel?>(context,label,DirectCollectionKind.ReferenceArray);document.Dispose();Assert.Throws<ObjectDisposedException>(()=>context.ReadCollection(label,DirectCollectionKind.ReferenceArray));Assert.Equal(label.Entry,references.Values[0]?.Entry);Assert.Null(references.Values[1]);}
 [Fact]public void OuterAbortAndUndoRedoRestoreExactArrayBoundsAndCustomGuid(){using var document=DocumentProjectionContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(document);var label=context.GetLabel("0:1");document.NewCommand();context.ReplaceCollection(label,DirectCollections.Array<int>(-3,[4,5]),BatchBICollectionWorkflow.Custom);Assert.True(document.CommitCommand(),"initial");document.NewCommand();context.ReplaceCollection(label,DirectCollections.Array<int>(19,[7]),BatchBICollectionWorkflow.Custom);document.AbortCommand();Assert.Equal(-3,BatchBICollectionWorkflow.Read<int>(context,label,DirectCollectionKind.IntegerArray,BatchBICollectionWorkflow.Custom).LowerBound);document.NewCommand();context.RemoveCollection(label,DirectCollectionKind.IntegerArray,BatchBICollectionWorkflow.Custom);Assert.True(document.CommitCommand(),"remove");Assert.Null(context.ReadCollection(label,DirectCollectionKind.IntegerArray,BatchBICollectionWorkflow.Custom));Assert.True(document.Undo(),"undo remove");Assert.Equal(ExpectedOriginal,BatchBICollectionWorkflow.Read<int>(context,label,DirectCollectionKind.IntegerArray,BatchBICollectionWorkflow.Custom).Values);Assert.True(document.Redo(),"redo remove");Assert.Null(context.ReadCollection(label,DirectCollectionKind.IntegerArray,BatchBICollectionWorkflow.Custom));}
 [Theory][InlineData(DocumentStorageFormat.BinXcaf)][InlineData(DocumentStorageFormat.XmlXcaf)]public void SupportedEmptyDirectArraysAndListsRemainDistinctFromMissingAfterReopen(DocumentStorageFormat format){string path=Path.Combine(Path.GetTempPath(),"BI-empty-"+Guid.NewGuid()+(format==DocumentStorageFormat.BinXcaf?".xbf":".xml"));try{using var document=XdeDocument.Create();using(var command=document.BeginTransaction("empty direct attributes")){var label=document.Projections.GetLabel("0:1");document.Projections.ReplaceCollections([new(label,DirectCollectionKind.IntegerArray,DirectCollections.Array(9,Array.Empty<int>())),new(label,DirectCollectionKind.RealArray,DirectCollections.Array(-3,Array.Empty<double>())),new(label,DirectCollectionKind.StringArray,DirectCollections.Array(17,Array.Empty<string>())),new(label,DirectCollectionKind.ByteArray,DirectCollections.Array(-6,Array.Empty<byte>())),new(label,DirectCollectionKind.ReferenceArray,DirectCollections.Array<DocumentProjectionLabel?>(4,[])),new(label,DirectCollectionKind.IntegerList,DirectCollections.List(Array.Empty<int>())),new(label,DirectCollectionKind.RealList,DirectCollections.List(Array.Empty<double>())),new(label,DirectCollectionKind.StringList,DirectCollections.List(Array.Empty<string>()))]);Assert.True(command.Commit());}document.Save(path,format);using var reopened=XdeDocument.Open(path);var root=reopened.Projections.GetLabel("0:1");foreach(var pair in new[]{(DirectCollectionKind.IntegerArray,9),(DirectCollectionKind.RealArray,-3),(DirectCollectionKind.StringArray,17),(DirectCollectionKind.ByteArray,-6),(DirectCollectionKind.ReferenceArray,4),(DirectCollectionKind.IntegerList,0),(DirectCollectionKind.RealList,0),(DirectCollectionKind.StringList,0)}){var snapshot=reopened.Projections.ReadCollection(root,pair.Item1);Assert.NotNull(snapshot);Assert.Equal(0,snapshot.Value.Count);Assert.Equal(pair.Item2,snapshot.Value.LowerBound);}Assert.Null(reopened.Projections.ReadCollection(root,DirectCollectionKind.BooleanArray));Assert.Null(reopened.Projections.Snapshot(root).NamedData);}finally{File.Delete(path);}}
}
